def delete_duplicates(values):
    counts = {}
    for v in values:
        counts[v] = counts.get(v, 0) + 1                                   # count how many times each value appears
    return [v for v in values if counts[v] == 1]                           # keep only values that appear EXACTLY once


if __name__ == "__main__":
    print(delete_duplicates([1, 2, 3, 3, 4, 4, 5]))

