import java.util.*;

public class Main {
    List<Integer> deleteDuplicates(List<Integer> values) {
        Map<Integer, Integer> counts = new HashMap<>();
        for (int v : values) counts.merge(v, 1, Integer::sum);                     // count how many times each value appears
        List<Integer> result = new ArrayList<>();
        for (int v : values) {
            if (counts.get(v) == 1) result.add(v);                                    // keep only values that appear EXACTLY once
        }
        return result;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        List<Integer> values = Arrays.asList(1, 2, 3, 3, 4, 4, 5);
        System.out.println(solution.deleteDuplicates(values));
    }
}

