#include <bits/stdc++.h>
using namespace std;

vector<int> deleteDuplicates(vector<int>& values) {
    unordered_map<int, int> counts;
    for (int v : values) counts[v]++;                                             // count how many times each value appears
    vector<int> result;
    for (int v : values) {
        if (counts[v] == 1) result.push_back(v);                                     // keep only values that appear EXACTLY once
    }
    return result;
}

int main() {
    vector<int> values = {1, 2, 3, 3, 4, 4, 5};
    vector<int> result = deleteDuplicates(values);
    for (int v : result) cout << v << " ";
    cout << endl;
    return 0;
}

