import java.util.*;

public class Main {
    ListNode deleteDuplicates(ListNode head) {
        ListNode dummy = new ListNode(0, head);
        ListNode prev = dummy;
        ListNode node = head;
        while (node != null) {
            if (node.next != null && node.next.val == node.val) {
                int val = node.val;
                while (node != null && node.val == val) {                              // skip past the ENTIRE run of this duplicated value
                    node = node.next;
                }
                prev.next = node;                                                          // prev connects directly to whatever comes after the run
            } else {
                prev = node;                                                               // a unique value: keep it, advance prev normally
                node = node.next;
            }
        }
        return dummy.next;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        ListNode head = new ListNode(1, new ListNode(1, new ListNode(1, new ListNode(2, new ListNode(3)))));
        ListNode result = solution.deleteDuplicates(head);
        StringBuilder sb = new StringBuilder();
        while (result != null) { sb.append(result.val).append(" "); result = result.next; }
        System.out.println(sb.toString().trim());
    }
}

