ListNode* deleteDuplicates(ListNode* head) {
    ListNode dummy(0, head);
    ListNode* prev = &dummy;
    ListNode* node = head;
    while (node) {
        if (node->next && node->next->val == node->val) {
            int val = node->val;
            while (node && node->val == val) {                                          // skip past the ENTIRE run of this duplicated value
                node = node->next;
            }
            prev->next = node;                                                              // prev connects directly to whatever comes after the run
        } else {
            prev = node;                                                                     // a unique value: keep it, advance prev normally
            node = node->next;
        }
    }
    return dummy.next;
}

int main() {
    ListNode* head = new ListNode(1, new ListNode(1, new ListNode(1, new ListNode(2, new ListNode(3)))));
    ListNode* result = deleteDuplicates(head);
